head.script:
// 테스트 설명, 유효성 값 설정
//  - 담당 범위 : searchTarget 값별 검색 대상 (propval 전 항목) + 편집 모드 전환 시 표시값
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
//  - 아이템의 Label 과 Value 를 서로 다르게 구성하여 검색 결과와 편집 모드 표시값의 차이가 드러나도록 함
scwin.tData = {
    "description" : "[column > P > searchTarget]<br/>inputType='autoComplete' 인 Column 이 편집 상태일때 입력값을 비교/검색할 대상을 설정합니다.",
    "validation" : [
        "label 설정 시, 입력값을 아이템의 Label 값에서 검색하여 목록에 표시합니다.",
        "미설정 시, 입력값을 아이템의 Label 값에서 검색하여 목록에 표시합니다.",
        "label 설정 시, 편집 모드로 전환 시 Cell 값에 해당하는 아이템의 Label 값이 표시됩니다.",
        "value 설정 시, 입력값을 아이템의 Value 값에서 검색하여 목록에 표시합니다.",
        "value 설정 시, 편집 모드로 전환 시 Cell 값에 해당하는 아이템의 Value 값이 표시됩니다.",
        "both 설정 시, 입력값을 아이템의 Label 과 Value 값에서 모두 검색하여 목록에 표시합니다.",
        "both 설정 시, 편집 모드로 전환 시 Cell 값에 해당하는 아이템의 Label 값이 표시됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_searchTarget.setValue("label");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - name : 안내 Column (readOnly) / fruit : 검증 대상 autoComplete Column (searchTarget = con 값)
//  - 아이템(Label / Value) : Apple / B100, Banana / A100, Cherry / C100, Avocado / D100
//  - Row 0 = B100 (Apple), Row 1 = A100 (Banana), Row 2 = C100 (Cherry)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cSearchTarget = con_searchTarget.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 아이템(Label / Value) : Apple / B100, Banana / A100, Cherry / C100, Avocado / D100\n[절차] fruit 셀 더블클릭 -> 입력창 표시값 확인 -> 입력값을 지우고 A 또는 B 입력 -> 다시 지우고 전체 값 A100 또는 Apple 입력\n[확인] 편집 진입 시 입력창 표시값, 입력값으로 표시되는 아이템 목록(검색 대상이 아닌 쪽 전체 값 입력 시 목록 미표시 - label/미설정 : A100, value : Apple), 아이템 선택 후 출력되는 Cell 값"', '', 'label1');

    let attrCol = '';
    if (cSearchTarget !== '') {
        attrCol += ' searchTarget="' + cSearchTarget + '"';
    }

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="fruit" name="fruit" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "fruit" : "B100" },
        { "name" : "김철수", "fruit" : "A100" },
        { "name" : "이영희", "fruit" : "C100" }
    ], false);

    // 정적 아이템 (Label 과 Value 를 서로 다르게 구성)
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>Apple</w2:label><w2:value>B100</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>Banana</w2:label><w2:value>A100</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>Cherry</w2:label><w2:value>C100</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>Avocado</w2:label><w2:value>D100</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:400px;height:250px;"'
        + ' ev:onafteredit="scwin.target1_onafteredit">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="230" style="" inputType="text" id="column2" value="fruit (autoComplete)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="230" style="" inputType="autoComplete" id="fruit" value=""' + attrCol + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 편집 완료 시 Cell 값 / 표시값 출력
//  - validation 1, 2, 4, 6 : 목록에서 선택한 아이템이 Cell 값으로 설정되었는지 확인 (목록 표시는 화면 관찰)
//  - validation 3, 5, 7 : 편집 진입 시 입력창 표시값은 화면 관찰
scwin.target1_onafteredit = function (rowIndex, colIndex, value) {
    wf_body_bottom.getObj("scwin").setReturnValue("편집 완료 Row " + rowIndex + " -> Cell 값 : '" + target1.getCellData(rowIndex, "fruit") + "' (표시 : '" + target1.getCellDisplayData(rowIndex, "fruit") + "')");
};
